mapper.select:
WITH ranked AS (
SELECT id, shared_at, actor_user_id, object_type, object_id,
ROW_NUMBER() OVER (
PARTITION BY object_type, object_id
ORDER BY shared_at DESC, id DESC
) AS rn
FROM user_inbox
WHERE recipient_user_id = #{userId}
AND deleted_at IS NULL
)
SELECT id, shared_at, actor_user_id, object_type, object_id
FROM ranked
WHERE rn = 1

    AND (
    shared_at < #{sharedAt}
    OR (shared_at = #{sharedAt} AND id < #{id})
    )

ORDER BY shared_at DESC, id DESC
LIMIT #{rowCount}
